class Solution {
public:
    int minimumOperations(TreeNode* root) {
        int ans = 0;
        queue<TreeNode*> q;
        q.push(root);
        while (!q.empty()) {
            int sz = q.size();
            vector<int> level(sz);
            for (int i = 0; i < sz; i++) {
                TreeNode* node = q.front();
                q.pop();
                level[i] = node->val;
                if (node->left) q.push(node->left);
                if (node->right) q.push(node->right);
            }
            ans += countSwaps(level);
        }
        return ans;
    }
private:
    int countSwaps(vector<int>& arr) {
        int n = arr.size();
        if (n <= 1) return 0;
        vector<int> sorted = arr;
        sort(sorted.begin(), sorted.end());
        unordered_map<int, int> targetPos;
        for (int i = 0; i < n; i++) targetPos[sorted[i]] = i;
        vector<bool> visited(n, false);
        int swaps = 0;
        for (int i = 0; i < n; i++) {
            if (visited[i]) continue;
            int cycleLen = 0;
            int j = i;
            while (!visited[j]) {
                visited[j] = true;
                j = targetPos[arr[j]];
                cycleLen++;
            }
            swaps += cycleLen - 1;
        }
        return swaps;
    }
};
